:root {
  --bg-card: #f7f0e3;
  --border-dark: #5c3d1e;
  --header-bg: #5c3d1e;
  --header-text: #f7f0e3;
  --label-text: #7a5230;
  --cell-empty: #e8ddc8;
  --cell-filled: #5c3d1e;
  --cell-accent: #b85c2a;
  --spec-bg: #efe4cc;
  --spec-border: #c9a97a;
  --spec-key: #7a5230;
  --spec-val: #2e1a0e;
  --footer-bg: #e8ddc8;
  --badge-bg: #4a7c4e;
  --badge-text: #f7f0e3;
  --grid-label: #9b6e3a;
}

article.draft-card {
  background-color: var(--bg-card);
  border: 2px solid var(--border-dark);
  border-radius: 6px;
  width: 480px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.card-header {
  background-color: var(--header-bg);
  color: var(--header-text);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 14px;
}

.studio-label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.card-id {
  font-size: 11px;
  font-weight: 400;
  letter-spacing: 0.08em;
  opacity: 0.85;
}

.card-body {
  display: flex;
  flex-direction: row;
  gap: 14px;
  padding: 14px;
}

.pattern-grid {
  display: grid;
  grid-template-columns: 72px 1fr;
  grid-template-rows: repeat(3, auto);
  gap: 8px 8px;
  align-items: center;
  flex: 1;
}

.grid-label {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--grid-label);
  text-align: right;
  padding-right: 6px;
}

.grid-cells {
  display: flex;
  flex-direction: row;
  gap: 4px;
}

.cell {
  display: inline-block;
  width: 20px;
  height: 20px;
  border-radius: 3px;
  border: 1.5px solid var(--spec-border);
  background-color: var(--cell-empty);
}

.cell.filled {
  background-color: var(--cell-filled);
  border-color: var(--border-dark);
}

.cell.filled.accent {
  background-color: var(--cell-accent);
  border-color: var(--cell-accent);
}

.spec-panel {
  background-color: var(--spec-bg);
  border: 1.5px solid var(--spec-border);
  border-radius: 5px;
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 148px;
}

.spec-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 8px;
}

.spec-key {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: var(--spec-key);
}

.spec-val {
  font-size: 11px;
  font-weight: 600;
  color: var(--spec-val);
  text-align: right;
}

.card-footer {
  background-color: var(--footer-bg);
  border-top: 1.5px solid var(--spec-border);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 7px 14px;
}

.weaver-name {
  font-size: 11px;
  font-weight: 600;
  color: var(--label-text);
  font-style: italic;
}

.draft-date {
  font-size: 11px;
  color: var(--spec-key);
  letter-spacing: 0.04em;
}

.status-badge {
  background-color: var(--badge-bg);
  color: var(--badge-text);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 2px 8px;
  border-radius: 10px;
}
